libcurvefs
===

SDK C/C++ library for CurveFS.

Example
===

```c
#include "libcurvefs.h"

int instance = curvefs_create();
curvefs_conf_set(instance, "s3.ak", "xxx")
curvefs_conf_set(instance, "s3.sk", "xxx")

...

int rc = curvefs_mount(instance, "fsname", "/);
if (rc != 0) {
    // mount failed
}

rc = curvefs_mkdir(instance_ptr, "/mydir")
if (rc != 0) {
    // mkdir failed
}
```

See [examples](examples) for more examples.

#include <fcntl.h>

#include "common.h"

int
main(int argc, char** argv) {
    exact_args(argc, 2);

    uintptr_t instance = curvefs_create();
    load_cfg_from_environ(instance);

    char* fsname = get_filesystem_name();
    char* mountpoint = get_mountpoint();
    int rc = curvefs_mount(instance, fsname, mountpoint);
    if (rc != 0) {
        fprintf(stderr, "mount failed: retcode = %d\n", rc);
        return rc;
    }

    int fd = curvefs_open(instance, argv[1], O_WRONLY, 0777);
    if (fd != 0) {
        rc = fd;
        fprintf(stderr, "open failed: retcode = %d\n", rc);
        return rc;
    }

    rc = curvefs_lseek(instance, fd, 0, SEEK_END);
    if (rc != 0) {
        fprintf(stderr, "lseek failed: retcode = %d\n", rc);
        return rc;
    }

    ssize_t n = curvefs_write(instance, fd, argv[2], strlen(argv[2]));
    if (n < 0) {
        rc = n;
        fprintf(stderr, "write failed: retcode = %d\n", rc);
        return rc;
    } else if (n != strlen(argv[2])) {
        fprintf(stderr, "write failed: %zd != %zu\n", n, strlen(argv[2]));
        return -1;
    }

    rc = curvefs_close(instance, fd);
    if (rc != 0) {
        fprintf(stderr, "close failed: retcode = %d\n", rc);
    }
    return 0;
}

#include "common.h"

int
main(int argc, char** argv) {
    exact_args(argc, 2);

    uintptr_t instance = curvefs_create();
    load_cfg_from_environ(instance);

    char* fsname = get_filesystem_name();
    char* mountpoint = get_mountpoint();
    int rc = curvefs_mount(instance, fsname, mountpoint);
    if (rc != 0) {
        fprintf(stderr, "mount failed: retcode = %d\n", rc);
        return rc;
    }

    rc = curvefs_chmod(instance, argv[1], atoi(argv[2]));
    if (rc != 0) {
        fprintf(stderr, "chmod failed: retcode = %d\n", rc);
        return rc;
    }
    return 0;
}

