#ifndef CURVEFS_SDK_LIBCURVEFS_EXAMPLES_COMMON_H_
#define CURVEFS_SDK_LIBCURVEFS_EXAMPLES_COMMON_H_

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#include "curvefs/sdk/libcurvefs/libcurvefs.h"

const char* KEY_FSNAME = "curvefs.name";
const char* KEY_MDS_ADDRS = "mdsOpt.rpcRetryOpt.addrs";

char*
require_string(const char* name) {
    char* value = getenv(name);
    if (strlen(value) == 0) {
        fprintf(stderr, "require %s\n", name);
        exit(1);
    }
    return value;
}

char*
get_filesystem_name() {
    //return require_string(KEY_FSNAME);
    return "perf02";
}

char*
get_mountpoint() {
    return "/";
}

void
load_cfg_from_environ(uintptr_t instance) {
    //curvefs_conf_set(instance, KEY_MDS_ADDRS, require_string(KEY_MDS_ADDRS));
    curvefs_conf_set(instance, KEY_MDS_ADDRS, "10.221.103.160:6700,10.221.103.160:6701,10.221.103.160:6702");
    curvefs_conf_set(instance, "client.common.logDir", "/tmp");
    curvefs_conf_set(instance, "fs.accessLogging", "true");
    curvefs_conf_set(instance, "client.loglevel", "6");
    curvefs_conf_set(instance, "diskCache.diskCacheType", "0");
}

void
exact_args(int argc, int number) {
    if (--argc == number) {
        return;
    }

    fprintf(stderr, "requires exactly %d argument[s]\n", number);
    exit(1);
}

#endif  // CURVEFS_SDK_LIBCURVEFS_EXAMPLES_COMMON_H_

#include <fcntl.h>

#include "common.h"

int
main(int argc, char** argv) {
    exact_args(argc, 1);

    uintptr_t instance = curvefs_create();
    load_cfg_from_environ(instance);

    char* fsname = get_filesystem_name();
    char* mountpoint = get_mountpoint();
    int rc = curvefs_mount(instance, fsname, mountpoint);
    if (rc != 0) {
        fprintf(stderr, "mount failed: retcode = %d\n", rc);
        return rc;
    }

    int fd = curvefs_open(instance, argv[1], O_WRONLY, 0777);
    if (fd != 0) {
        rc = fd;
        fprintf(stderr, "open failed: retcode = %d\n", rc);
        return rc;
    }

    struct stat stat;
    rc = curvefs_fstat(instance, fd, &stat);
    if (rc != 0) {
        fprintf(stderr, "fstat failed: retcode = %d\n", rc);
        return rc;
    }

    printf("ino=%d, size=%d\n", stat.st_ino, stat.st_size);
    return 0;
}

#include "common.h"

int
main(int argc, char** argv) {
    exact_args(argc, 1);

    uintptr_t instance = curvefs_create();
    load_cfg_from_environ(instance);

    // mount
    char* fsname = get_filesystem_name();
    char* mountpoint = get_mountpoint();
    int rc = curvefs_mount(instance, fsname, mountpoint);
    if (rc != 0) {
        fprintf(stderr, "mount failed: retcode = %d\n", rc);
        return rc;
    }

    // opendir
    uint64_t fd;
    rc = curvefs_opendir(instance, argv[1], &fd);
    if (rc != 0) {
        fprintf(stderr, "opendir failed: retcode = %d\n", rc);
        return rc;
    }

    // readdir
    dirent_t dirents[8192];
    for ( ;; ) {
        ssize_t n = curvefs_readdir(instance, fd, dirents, 8192);
        if (n < 0) {
            rc = n;
            fprintf(stderr, "readdir failed: retcode = %d\n", rc);
            break;
        } else if (n == 0) {
            break;
        }

        for (int i = 0; i < n; i++) {
            printf("%s: ino=%d size=%d\n", dirents[i].name,
                                           dirents[i].stat.st_ino,
                                           dirents[i].stat.st_size);
        }
    }

    rc = curvefs_closedir(instance, fd);
    if (rc != 0) {
        fprintf(stderr, "closedir failed: retcode = %d\n", rc);
    }
    return rc;
}

