 * @param a an array to fill
 * @param <T> type of array elements
 * @return supplied array
 */
<T> T[] keysToArray(T[] a) {
    Object[] r = a;
    Node<K,V>[] tab;
    int idx = 0;
    if (size > 0 && (tab = table) != null) {
        for (Node<K,V> e : tab) {
            for (; e != null; e = e.next) {
                r[idx++] = e.key;
            }
        }
    }
    return a;
}

