    if (a != null && a.stack != null) {
        Object r;
        if ((r = a.result) == null)
            a.cleanStack();
        if (mode >= 0 && (r != null || a.result != null))
            a.postComplete();
    }
    if (result != null && stack != null) {
        if (mode < 0)
            return this;
        else
            postComplete();
    }
    return null;
}

