/* ------------- Signallers -------------- */

/**
 * Completion for recording and releasing a waiting thread.  This
 * class implements ManagedBlocker to avoid starvation when
 * blocking actions pile up in ForkJoinPools.
 */
@SuppressWarnings("serial")
static final class Signaller extends Completion
    implements ForkJoinPool.ManagedBlocker {
    long nanos;                    // remaining wait time if timed
    final long deadline;           // non-zero if timed
    final boolean interruptible;
    boolean interrupted;
    volatile Thread thread;

    Signaller(boolean interruptible, long nanos, long deadline) {
        this.thread = Thread.currentThread();
        this.interruptible = interruptible;
        this.nanos = nanos;
        this.deadline = deadline;
    }
    final CompletableFuture<?> tryFire(int ignore) {
        Thread w; // no need to atomically claim
        if ((w = thread) != null) {
            thread = null;
            LockSupport.unpark(w);
        }
        return null;
    }
    public boolean isReleasable() {
        if (Thread.interrupted())
            interrupted = true;
        return ((interrupted && interruptible) ||
                (deadline != 0L &&
                 (nanos <= 0L ||
                  (nanos = deadline - System.nanoTime()) <= 0L)) ||
                thread == null);
    }
    public boolean block() {
        while (!isReleasable()) {
            if (deadline == 0L)
                LockSupport.park(this);
            else
                LockSupport.parkNanos(this, nanos);
        }
        return true;
    }
    final boolean isLive() { return thread != null; }
}

/**
 * Returns raw result after waiting, or null if interruptible and
 * interrupted.
 */
private Object waitingGet(boolean interruptible) {
    if (interruptible && Thread.interrupted())
        return null;
    Signaller q = null;
    boolean queued = false;
    Object r;
    while ((r = result) == null) {
        if (q == null) {
            q = new Signaller(interruptible, 0L, 0L);
            if (Thread.currentThread() instanceof ForkJoinWorkerThread wt)
                ForkJoinPool.helpAsyncBlocker(wt.pool, q);
        }
        else if (!queued)
            queued = tryPushStack(q);
        else if (interruptible && q.interrupted) {
            q.thread = null;
            cleanStack();
            return null;
        }
        else {
            try {
                ForkJoinPool.managedBlock(q);
            } catch (InterruptedException ie) { // currently cannot happen
                q.interrupted = true;
            }
        }
    }
    if (q != null) {
        q.thread = null;
        if (q.interrupted)
            Thread.currentThread().interrupt();
    }
    postComplete();
    return r;
}

/**
 * Returns raw result after waiting, or null if interrupted, or
 * throws TimeoutException on timeout.
 */
private Object timedGet(long nanos) throws TimeoutException {
    long d = System.nanoTime() + nanos;
    long deadline = (d == 0L) ? 1L : d; // avoid 0
    boolean interrupted = false, queued = false;
    Signaller q = null;
    Object r = null;
    for (;;) { // order of checking interrupt, result, timeout matters
        if (interrupted || (interrupted = Thread.interrupted()))
            break;
        else if ((r = result) != null)
            break;
        else if (nanos <= 0L)
            break;
        else if (q == null) {
            q = new Signaller(true, nanos, deadline);
            if (Thread.currentThread() instanceof ForkJoinWorkerThread wt)
                ForkJoinPool.helpAsyncBlocker(wt.pool, q);
        }
        else if (!queued)
            queued = tryPushStack(q);
        else {
            try {
                ForkJoinPool.managedBlock(q);
                interrupted = q.interrupted;
                nanos = q.nanos;
            } catch (InterruptedException ie) {
                interrupted = true;
            }
        }
    }
    if (q != null) {
        q.thread = null;
        if (r == null)
            cleanStack();
    }
    if (r != null) {
        if (interrupted)
            Thread.currentThread().interrupt();
        postComplete();
        return r;
    } else if (interrupted)
        return null;
    else
        throw new TimeoutException();
}

