@Override
public T resultNow() {
    Object r = result;
    if (r != null) {
        if (r instanceof AltResult alt) {
            if (alt.ex == null) return null;
        } else {
            @SuppressWarnings("unchecked")
            T t = (T) r;
            return t;
        }
