      "token": "デス",
      "start_offset": 8,
      "end_offset": 10,
      "type": "word",
      "position": 5
    }
  ]
}
```

## Example: Romaji reading

The following example creates an analyzer that outputs romaji transliterations:

```json
PUT /kuromoji-reading-romaji-index
{
  "settings": {
    "analysis": {
      "filter": {
        "romaji_reading": {
          "type": "kuromoji_readingform",
          "use_romaji": true
        }
      },
      "analyzer": {
        "romaji_analyzer": {
          "type": "custom",
