rest: POST /_aliases
body: |
{
  "actions": [
    {
      "add": {
        "index": "application_logs_2024",
        "alias": "logs_current"
      }
    }
  ]
}
-->
{% capture step1_rest %}
POST /_aliases
{
  "actions": [
    {
      "add": {
        "index": "application_logs_2024",
        "alias": "logs_current"
      }
    }
  ]
}
{% endcapture %}

{% capture step1_python %}


response = client.indices.update_aliases(
  body =   {
    "actions": [
      {
        "add": {
          "index": "application_logs_2024",
          "alias": "logs_current"
        }
      }
    ]
  }
)

{% endcapture %}

{% include code-block.html
    rest=step1_rest
    python=step1_python %}
<!-- spec_insert_end -->

