    "number_of_shards": 1,
    "number_of_replicas": 1
  }
}
-->
{% capture step1_rest %}
PUT /inventory
{
  "settings": {
    "index.write.wait_for_active_shards": "2",
    "number_of_shards": 1,
    "number_of_replicas": 1
  }
}
{% endcapture %}

{% capture step1_python %}

response = client.indices.create(
  index = "inventory",
  body =   {
    "settings": {
      "index.write.wait_for_active_shards": "2",
      "number_of_shards": 1,
      "number_of_replicas": 1
    }
  }
)

{% endcapture %}

{% include code-block.html
